CREATE TABLE IF NOT EXISTS "teras_diagnostic_templates" ("id" text PRIMARY KEY NOT NULL,"framework_id" text NOT NULL REFERENCES "teras_competency_frameworks"("id"),"pathway_id" text NOT NULL REFERENCES "teras_pathways"("id"),"version" text NOT NULL,"name" text NOT NULL,"description" text NOT NULL,"status" text DEFAULT 'draft' NOT NULL,"dimensions" text[] DEFAULT '{}' NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "teras_diagnostic_templates_pathway_version_unique" ON "teras_diagnostic_templates" ("pathway_id","version");
CREATE TABLE IF NOT EXISTS "teras_diagnostic_questions" ("id" text PRIMARY KEY NOT NULL,"template_id" text NOT NULL REFERENCES "teras_diagnostic_templates"("id") ON DELETE CASCADE,"framework_id" text NOT NULL REFERENCES "teras_competency_frameworks"("id"),"competency_unit_id" text REFERENCES "teras_competency_units"("id"),"dimension" text NOT NULL,"prompt" text NOT NULL,"sequence" integer NOT NULL,"required" boolean DEFAULT true NOT NULL,"metadata" jsonb DEFAULT '{}' NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL, CONSTRAINT "teras_diagnostic_questions_sequence_check" CHECK ("sequence" > 0));
CREATE UNIQUE INDEX IF NOT EXISTS "teras_diagnostic_questions_template_sequence_unique" ON "teras_diagnostic_questions" ("template_id","sequence");
CREATE TABLE IF NOT EXISTS "teras_diagnostic_options" ("id" text PRIMARY KEY NOT NULL,"question_id" text NOT NULL REFERENCES "teras_diagnostic_questions"("id") ON DELETE CASCADE,"code" text NOT NULL,"label" text NOT NULL,"score" integer DEFAULT 0 NOT NULL,"safety_outcome" text,"metadata" jsonb DEFAULT '{}' NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL, CONSTRAINT "teras_diagnostic_options_score_check" CHECK ("score" BETWEEN 0 AND 3));
CREATE UNIQUE INDEX IF NOT EXISTS "teras_diagnostic_options_question_code_unique" ON "teras_diagnostic_options" ("question_id","code");
CREATE TABLE IF NOT EXISTS "teras_diagnostic_sessions" ("id" text PRIMARY KEY NOT NULL,"learner_id" text NOT NULL REFERENCES "teras_people"("id") ON DELETE CASCADE,"enrollment_id" text NOT NULL REFERENCES "teras_enrollments"("id") ON DELETE CASCADE,"pathway_id" text NOT NULL REFERENCES "teras_pathways"("id"),"template_id" text NOT NULL REFERENCES "teras_diagnostic_templates"("id"),"framework_id" text NOT NULL REFERENCES "teras_competency_frameworks"("id"),"status" text DEFAULT 'in_progress' NOT NULL,"progress" integer DEFAULT 0 NOT NULL,"completed_at" timestamptz,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL, CONSTRAINT "teras_diagnostic_sessions_progress_check" CHECK ("progress" BETWEEN 0 AND 100));
CREATE INDEX IF NOT EXISTS "teras_diagnostic_sessions_learner_pathway_idx" ON "teras_diagnostic_sessions" ("learner_id","pathway_id");
CREATE TABLE IF NOT EXISTS "teras_diagnostic_responses" ("id" text PRIMARY KEY NOT NULL,"session_id" text NOT NULL REFERENCES "teras_diagnostic_sessions"("id") ON DELETE CASCADE,"question_id" text NOT NULL REFERENCES "teras_diagnostic_questions"("id"),"option_id" text NOT NULL REFERENCES "teras_diagnostic_options"("id"),"framework_id" text NOT NULL REFERENCES "teras_competency_frameworks"("id"),"competency_unit_id" text REFERENCES "teras_competency_units"("id"),"answered_at" timestamptz DEFAULT now() NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "teras_diagnostic_responses_session_question_unique" ON "teras_diagnostic_responses" ("session_id","question_id");
CREATE TABLE IF NOT EXISTS "teras_diagnostic_profiles" ("id" text PRIMARY KEY NOT NULL,"session_id" text NOT NULL REFERENCES "teras_diagnostic_sessions"("id"),"learner_id" text NOT NULL REFERENCES "teras_people"("id") ON DELETE CASCADE,"pathway_id" text NOT NULL REFERENCES "teras_pathways"("id"),"framework_id" text NOT NULL REFERENCES "teras_competency_frameworks"("id"),"framework_version" text NOT NULL,"current_state" text NOT NULL,"safety_override" boolean DEFAULT false NOT NULL,"completed_at" timestamptz DEFAULT now() NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "teras_diagnostic_profiles_session_unique" ON "teras_diagnostic_profiles" ("session_id");
CREATE INDEX IF NOT EXISTS "teras_diagnostic_profiles_learner_pathway_idx" ON "teras_diagnostic_profiles" ("learner_id","pathway_id","completed_at");
CREATE TABLE IF NOT EXISTS "teras_diagnostic_profile_items" ("id" text PRIMARY KEY NOT NULL,"profile_id" text NOT NULL REFERENCES "teras_diagnostic_profiles"("id") ON DELETE CASCADE,"competency_unit_id" text NOT NULL REFERENCES "teras_competency_units"("id"),"framework_id" text NOT NULL REFERENCES "teras_competency_frameworks"("id"),"state" text NOT NULL,"score" integer DEFAULT 0 NOT NULL,"evidence_level" text DEFAULT 'none' NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "teras_diagnostic_profile_items_profile_unit_unique" ON "teras_diagnostic_profile_items" ("profile_id","competency_unit_id");
CREATE TABLE IF NOT EXISTS "teras_diagnostic_gaps" ("id" text PRIMARY KEY NOT NULL,"profile_id" text NOT NULL REFERENCES "teras_diagnostic_profiles"("id") ON DELETE CASCADE,"competency_unit_id" text NOT NULL REFERENCES "teras_competency_units"("id"),"framework_id" text NOT NULL REFERENCES "teras_competency_frameworks"("id"),"diagnosis" text NOT NULL,"severity" text NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL);
CREATE TABLE IF NOT EXISTS "teras_diagnostic_recommendations" ("id" text PRIMARY KEY NOT NULL,"profile_id" text NOT NULL REFERENCES "teras_diagnostic_profiles"("id") ON DELETE CASCADE,"competency_unit_id" text REFERENCES "teras_competency_units"("id"),"framework_id" text NOT NULL REFERENCES "teras_competency_frameworks"("id"),"module_id" text REFERENCES "teras_modules"("id"),"practice_task_id" text REFERENCES "teras_practice_tasks"("id"),"evidence_requirement_id" text REFERENCES "teras_evidence_requirements"("id"),"kind" text NOT NULL,"title" text NOT NULL,"rationale" text NOT NULL,"priority" text NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL);
CREATE TABLE IF NOT EXISTS "teras_diagnostic_safety_flags" ("id" text PRIMARY KEY NOT NULL,"profile_id" text NOT NULL REFERENCES "teras_diagnostic_profiles"("id") ON DELETE CASCADE,"competency_unit_id" text REFERENCES "teras_competency_units"("id"),"code" text NOT NULL,"severity" text NOT NULL,"blocking" boolean DEFAULT true NOT NULL,"detail" text NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL);
CREATE TABLE IF NOT EXISTS "teras_diagnostic_audit_events" ("id" text PRIMARY KEY NOT NULL,"session_id" text NOT NULL REFERENCES "teras_diagnostic_sessions"("id") ON DELETE CASCADE,"learner_id" text NOT NULL REFERENCES "teras_people"("id") ON DELETE CASCADE,"action" text NOT NULL,"details" jsonb DEFAULT '{}' NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"created_by" text DEFAULT 'system' NOT NULL);
CREATE INDEX IF NOT EXISTS "teras_diagnostic_audit_session_created_idx" ON "teras_diagnostic_audit_events" ("session_id","created_at");
ALTER TABLE "teras_diagnostic_questions" ADD COLUMN IF NOT EXISTS "question_type" text DEFAULT 'single_choice' NOT NULL, ADD COLUMN IF NOT EXISTS "explanation" text, ADD COLUMN IF NOT EXISTS "difficulty" text DEFAULT 'core' NOT NULL;
ALTER TABLE "teras_diagnostic_options" ADD COLUMN IF NOT EXISTS "safety_flag" boolean DEFAULT false NOT NULL;
ALTER TABLE "teras_diagnostic_profiles" ADD COLUMN IF NOT EXISTS "dimension_summaries" jsonb DEFAULT '{}' NOT NULL;
ALTER TABLE "teras_diagnostic_profile_items" ADD COLUMN IF NOT EXISTS "unit_code" text DEFAULT '' NOT NULL, ADD COLUMN IF NOT EXISTS "unit_title" text DEFAULT '' NOT NULL;
ALTER TABLE "teras_diagnostic_gaps" ADD COLUMN IF NOT EXISTS "unit_code" text DEFAULT '' NOT NULL, ADD COLUMN IF NOT EXISTS "unit_title" text DEFAULT '' NOT NULL;
ALTER TABLE "teras_diagnostic_recommendations" ADD COLUMN IF NOT EXISTS "unit_code" text DEFAULT '' NOT NULL, ADD COLUMN IF NOT EXISTS "unit_title" text DEFAULT '' NOT NULL, ADD COLUMN IF NOT EXISTS "simulation_id" text, ADD COLUMN IF NOT EXISTS "safety_rule_id" text, ADD COLUMN IF NOT EXISTS "href" text;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'teras_diagnostic_question_type_check') THEN
    ALTER TABLE "teras_diagnostic_questions" ADD CONSTRAINT "teras_diagnostic_question_type_check" CHECK ("question_type" IN ('single_choice','rating','experience','evidence','scenario'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'teras_diagnostic_safety_outcome_check') THEN
    ALTER TABLE "teras_diagnostic_options" ADD CONSTRAINT "teras_diagnostic_safety_outcome_check" CHECK ("safety_outcome" IS NULL OR "safety_outcome" IN ('SAFE','CRITICAL_SAFETY_FAILURE'));
  END IF;
END $$;